"""Inline escape and character-reference decoding helpers."""

from html.entities import html5
import re


_ASCII_PUNCTUATION = frozenset(
    "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"
)
_NAMED = re.compile(r"&([A-Za-z][A-Za-z0-9]+);")
_NUMERIC = re.compile(r"&#(?:([0-9]{1,7})|[xX]([0-9A-Fa-f]{1,6}));")
_BACKTICK_RUN = re.compile(r"`+")


def _numeric_character(decimal: str | None, hexadecimal: str | None) -> str:
    codepoint = int(decimal, 10) if decimal is not None else int(hexadecimal, 16)
    if codepoint == 0 or codepoint > 0x10FFFF or 0xD800 <= codepoint <= 0xDFFF:
        codepoint = 0xFFFD
    return chr(codepoint)


def decode_escapes_and_entities(text: str) -> str:
    """Decode eligible CommonMark backslash escapes and semicolon references."""
    output: list[str] = []
    i = 0
    while i < len(text):
        if text[i] == "\\" and i + 1 < len(text) and text[i + 1] in _ASCII_PUNCTUATION:
            output.append(text[i + 1])
            i += 2
            continue
        if text[i] == "&":
            numeric = _NUMERIC.match(text, i)
            if numeric:
                output.append(_numeric_character(numeric.group(1), numeric.group(2)))
                i = numeric.end()
                continue
            named = _NAMED.match(text, i)
            if named:
                value = html5.get(named.group(1) + ";")
                if value is not None:
                    output.append(value)
                    i = named.end()
                    continue
        output.append(text[i])
        i += 1
    return "".join(output)


def render_inline(text: str) -> str:
    """Render the current inline subset, keeping code span contents literal."""
    import html

    output: list[str] = []
    cursor = 0
    while cursor < len(text):
        opener = _BACKTICK_RUN.search(text, cursor)
        if opener is None:
            output.append(html.escape(decode_escapes_and_entities(text[cursor:])))
            break
        output.append(html.escape(decode_escapes_and_entities(text[cursor:opener.start()])))
        length = opener.end() - opener.start()
        search = opener.end()
        closer = None
        while True:
            candidate = _BACKTICK_RUN.search(text, search)
            if candidate is None:
                break
            if candidate.end() - candidate.start() == length:
                closer = candidate
                break
            search = candidate.end()
        if closer is None:
            output.append(html.escape(text[opener.start():opener.end()]))
            cursor = opener.end()
            continue
        literal = text[opener.end():closer.start()].replace("\r\n", "\n").replace("\r", "\n").replace("\n", " ")
        if literal.startswith(" ") and literal.endswith(" ") and any(ch != " " for ch in literal):
            literal = literal[1:-1]
        output.append("<code>" + html.escape(literal) + "</code>")
        cursor = closer.end()
    return "".join(output)
from .model import Document, Node
from .references import collect_definitions
from .html_blocks import parse_html_block
from .block_quotes import parse_block_quote
from .lists import parse_list, parse_list_marker
from .inline import decode_escapes_and_entities, render_inline
import html
import re

_THEMATIC_BREAK = re.compile(r"(?:\*\s*){3,}|(?:-\s*){3,}|(?:_\s*){3,}\Z")


def _indent_columns(line: str) -> tuple[int, int]:
    columns = offset = 0
    while offset < len(line) and line[offset] in " \t":
        columns += 4 - columns % 4 if line[offset] == "\t" else 1
        offset += 1
    return columns, offset


def _remove_columns(line: str, amount: int) -> str:
    col = i = 0
    while i < len(line) and col < amount and line[i] in ' \t':
        n = 4 - col % 4 if line[i] == '\t' else 1
        if col + n > amount:
            return ' ' * (col + n - amount) + line[i+1:]
        col += n; i += 1
    return line[i:]


def _is_thematic_break(line: str) -> bool:
    columns, offset = _indent_columns(line)
    return columns <= 3 and bool(_THEMATIC_BREAK.fullmatch(line[offset:]))


def parse_blocks(markdown: str) -> Document:
    source = markdown.replace("\x00", "\ufffd").replace("\r\n", "\n").replace("\r", "\n")
    lines = source.splitlines(keepends=True)
    if source and not lines: lines = [source]
    children: list[Node] = []
    doc = Document(children=children)
    paragraph: list[str] = []

    def flush_paragraph():
        if paragraph:
            raw = '\n'.join(x.strip(' \t') for x in paragraph).strip(' \t')
            remainder = collect_definitions(raw + ('\n' if raw else ''), doc.references)
            if remainder.strip(): children.append(Node('paragraph', raw=remainder.rstrip('\n')))
            paragraph.clear()

    i = 0
    while i < len(lines):
        line = lines[i]; body = line.rstrip('\n')
        cols, off = _indent_columns(body)
        content = body[off:] if cols <= 3 else body
        quote = parse_block_quote(lines[i:])
        if quote:
            flush_paragraph()
            count, quote_lines = quote
            nested = parse_blocks(''.join(quote_lines))
            for key, value in nested.references.items():
                doc.references.setdefault(key, value)
            children.append(Node('block_quote', children=nested.children))
            i += count
            continue
        # Fenced code blocks.
        fm = re.match(r'^ {0,3}(`{3,}|~{3,})(.*)$', body)
        if fm:
            flush_paragraph(); fence, info = fm.group(1), fm.group(2).strip(' \t')
            if fence[0] == '`' and '`' in info: fm = None
            else:
                i += 1; literal = []
                while i < len(lines):
                    candidate = lines[i].rstrip('\n')
                    close = re.match(r'^ {0,3}(' + re.escape(fence[0]) + r'{'+str(len(fence))+r',})[ \t]*$', candidate)
                    if close: i += 1; break
                    literal.append(_remove_columns(candidate, min(3, len(body)-len(body.lstrip(' ')))) + ('\n' if lines[i].endswith('\n') else ''))
                    i += 1
                children.append(Node('code_block', literal=''.join(literal), info=info)); continue
        # ATX heading.
        hm = re.match(r'^ {0,3}(#{1,6})(?:[ \t]+(.*)|[ \t]*)$', body)
        if hm:
            flush_paragraph(); text = (hm.group(2) or '').strip(' \t')
            text = re.sub(r'[ \t]+#+[ \t]*$', '', text).strip(' \t')
            children.append(Node('heading', raw=text, level=len(hm.group(1)))); i += 1; continue
        # Setext underline converts the open paragraph.
        sm = re.match(r'^ {0,3}(=+|-+)[ \t]*$', body)
        if sm and paragraph:
            raw = '\n'.join(x.strip(' \t') for x in paragraph).strip(' \t')
            remainder = collect_definitions(raw + '\n', doc.references)
            if remainder.strip(): children.append(Node('heading', raw=remainder.rstrip('\n'), level=1 if sm.group(1)[0] == '=' else 2))
            paragraph.clear(); i += 1; continue
        if not body.strip(' \t'):
            flush_paragraph(); i += 1; continue
        # HTML blocks.
        html_result = parse_html_block(lines[i:], paragraph_open=bool(paragraph))
        if html_result:
            flush_paragraph(); count, raw = html_result; children.append(Node('html_block', raw=raw)); i += count; continue
        if _is_thematic_break(body):
            flush_paragraph(); children.append(Node('thematic_break')); i += 1; continue
        parsed_list = parse_list(lines[i:], paragraph_open=bool(paragraph))
        if parsed_list:
            flush_paragraph()
            count, list_node = parsed_list
            children.append(list_node)
            i += count
            continue
        # Indented code, only outside paragraphs.
        if cols >= 4 and not paragraph:
            code=[]
            while i < len(lines):
                b=lines[i].rstrip('\n'); c,_=_indent_columns(b)
                if not b.strip(' \t'):
                    code.append(''); i += 1; continue
                if c < 4: break
                code.append(_remove_columns(b,4)); i += 1
            while code and code[-1] == '': code.pop()
            literal=''.join(x+'\n' for x in code)
            if literal: children.append(Node('code_block', literal=literal))
            continue
        if _is_thematic_break(body):
            flush_paragraph(); children.append(Node('thematic_break'))
        else:
            paragraph.append(content)
        i += 1
    flush_paragraph()
    return doc


def parse_inlines(document: Document) -> Document:
    return document


def render_html(document: Document) -> str:
    out=[]
    for node in document.children:
        if node.type == 'heading':
            out.append(f'<h{node.level}>{render_inline(node.raw)}</h{node.level}>\n')
        elif node.type == 'paragraph': out.append(f'<p>{render_inline(node.raw)}</p>\n')
        elif node.type == 'thematic_break': out.append('<hr />\n')
        elif node.type == 'code_block':
            info = decode_escapes_and_entities(node.info)
            cls = f' class="language-{html.escape(info.split()[0], quote=True)}"' if info else ''
            out.append(f'<pre><code{cls}>{html.escape(node.literal)}</code></pre>\n')
        elif node.type == 'html_block': out.append(node.raw + ('' if node.raw.endswith('\n') else '\n'))
        elif node.type == 'block_quote':
            inner = render_html(Document(children=node.children))
            out.append('<blockquote>\n' + inner + '</blockquote>\n')
        elif node.type == 'list':
            parts = node.info.split(':')
            ordered = parts[0] == 'ordered'
            tight = len(parts) < 3 or parts[2] == 'tight'
            tag = 'ol' if ordered else 'ul'
            attr = f' start="{parts[1]}"' if ordered and parts[1] and parts[1] != '1' else ''
            out.append(f'<{tag}{attr}>\n')
            for item in node.children:
                inner = render_html(Document(children=item.children))
                if tight:
                    inner = re.sub(r'<p>(.*?)</p>\n', r'\1\n', inner, flags=re.S)
                out.append('<li>' + inner + '</li>\n')
            out.append(f'</{tag}>\n')
    return ''.join(out)
from dataclasses import dataclass, field


@dataclass
class Node:
    """A block or inline node; raw content is retained for later stages."""

    type: str
    children: list["Node"] = field(default_factory=list)
    raw: str = ""
    level: int | None = None
    literal: str = ""
    info: str = ""

    @property
    def raw_content(self) -> str:
        return self.raw


@dataclass
class Document:
    children: list[Node] = field(default_factory=list)
    references: dict[str, tuple[str, str | None]] = field(default_factory=dict)
from commonmark_parser import parse_blocks, parse_inlines, render_html
from commonmark_parser.inline import decode_escapes_and_entities


def test_ascii_punctuation_escape():
    assert decode_escapes_and_entities(r"\*") == "*"


def test_non_punctuation_backslash_remains_literal():
    assert decode_escapes_and_entities(r"\a") == r"\a"


def test_named_reference_requires_semicolon():
    assert decode_escapes_and_entities("&amp; &amp") == "& &amp"


def test_numeric_references_and_invalid_codepoints():
    assert decode_escapes_and_entities("&#65; &#x41; &#0; &#xD800;") == "A A \ufffd \ufffd"


def test_rendered_paragraph_decodes_then_html_escapes():
    document = parse_inlines(parse_blocks(r"A \* &amp; <"))
    assert render_html(document) == "<p>A * &amp; &lt;</p>\n"


def test_code_and_raw_html_keep_literal_content():
    document = parse_blocks("`&amp;`\n\n<div>&amp;</div>\n")
    assert render_html(document) == "<p><code>&amp;amp;</code></p>\n<div>&amp;</div>\n"


def test_code_spans_preserve_entities_escapes_and_escape_html():
    document = parse_inlines(parse_blocks(r"`&amp; \* <tag>`"))
    assert render_html(document) == "<p><code>&amp;amp; \\* &lt;tag&gt;</code></p>\n"


def test_code_span_matches_equal_maximal_backtick_run():
    document = parse_blocks("`` a ` b ``")
    assert render_html(document) == "<p><code>a ` b</code></p>\n"


def test_code_span_normalizes_newlines_and_one_edge_space():
    document = parse_blocks("`  a\nb  `")
    assert render_html(document) == "<p><code> a b </code></p>\n"


def test_unmatched_backtick_runs_remain_literal():
    document = parse_blocks("x `` y ` z")
    assert render_html(document) == "<p>x `` y ` z</p>\n"


def test_readme_describes_standard_streams():
